"""Write data/DATASET_STATISTICS.md from the actual generated files (and DB counts if reachable)."""

from __future__ import annotations

import asyncio
import json
import statistics
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from evaluation.data import EVAL_DIR, PROCESSED_DIR, read_jsonl  # noqa: E402


def table(counter: Counter, total: int) -> str:
    rows = ["| value | count | share |", "|---|---:|---:|"]
    for k, v in counter.most_common():
        rows.append(f"| {k} | {v} | {v / total:.1%} |")
    return "\n".join(rows)


async def db_counts() -> str:
    try:
        from sqlalchemy import text

        from app.core.database import dispose_engine, get_engine

        async with get_engine().connect() as conn:
            t = (await conn.execute(text("SELECT count(*) FROM tickets"))).scalar_one()
            k = (await conn.execute(text("SELECT count(*) FROM kb_articles"))).scalar_one()
            e = (await conn.execute(text("SELECT count(*) FROM tickets WHERE embedding IS NOT NULL"))).scalar_one()
        await dispose_engine()
        return f"Database (at report time): {t} tickets ({e} with embeddings), {k} KB articles."
    except Exception as exc:  # DB optional
        return f"Database not reachable at report time ({exc.__class__.__name__}); counts below are from files."


def main() -> None:
    tickets = read_jsonl(PROCESSED_DIR / "tickets.jsonl")
    wave2 = read_jsonl(PROCESSED_DIR / "tickets_wave2.jsonl")
    kb = read_jsonl(PROCESSED_DIR / "kb_articles.jsonl")
    kb2 = read_jsonl(PROCESSED_DIR / "kb_articles_wave2.jsonl")
    evals = {
        n: read_jsonl(EVAL_DIR / f"{n}.jsonl")
        for n in [
            "understanding_eval",
            "retrieval_eval",
            "generation_eval",
            "test",
            "novel_intent_eval",
            "groundedness_eval",
        ]
    }
    qrels = (EVAL_DIR / "retrieval_qrels.tsv").read_text(encoding="utf-8").splitlines()
    leakage = (
        json.loads((EVAL_DIR / "leakage_report.json").read_text())
        if (EVAL_DIR / "leakage_report.json").exists()
        else None
    )

    lengths = [len(t["complaint"].split()) for t in tickets]
    res_lengths = [len(t["resolution"].split()) for t in tickets]
    per_scenario = Counter(t["metadata"]["scenario_id"] for t in tickets)
    unresolved = sum(1 for t in tickets if not t["metadata"]["resolved"])
    grades = Counter(line.split()[3] for line in qrels if line.strip())

    out = [
        "# Dataset statistics",
        "",
        "Generated by `python scripts/report_dataset_stats.py` from the files actually produced by",
        "`scripts/generate_synthetic.py` (seed 42). Nothing here is estimated.",
        "",
        asyncio.run(db_counts()),
        "",
        "## Provenance",
        "",
        "* **Source:** `synthetic_template`: complaints and agent resolution notes are composed from 43 hand-authored",
        "  telecom scenarios (`scripts/datagen/scenarios.py`), each one root cause with a known fix, plus generic sentence",
        "  pools (openers, durations, business impact, emotional tone).",
        "* **Labels:** `generator_by_construction`: intent, products and severity come from the scenario (severity is",
        "  bumped one level when a business-impact sentence is included); sentiment is the tone of the emotion",
        "  sentence chosen. No LLM labelling, no human verification.",
        "* **KB articles:** `synthetic_authored`, one per scenario (symptoms, cause, numbered resolution steps).",
        "",
        "## Retrieval corpus (wave 1, ingested at launch)",
        "",
        f"* Tickets: **{len(tickets)}** across {len(per_scenario)} scenarios "
        f"(min {min(per_scenario.values())}, max {max(per_scenario.values())} per scenario; volume deliberately skewed)",
        f"* Tickets without a confirmed resolution (customer never responded): **{unresolved}**",
        f"* KB articles: **{len(kb)}**",
        f"* Complaint length (words): median {statistics.median(lengths)}, min {min(lengths)}, max {max(lengths)}",
        f"* Resolution length (words): median {statistics.median(res_lengths)}",
        f"* Date range: {min(t['created_at'] for t in tickets)[:10]} to {max(t['created_at'] for t in tickets)[:10]}",
        "",
        "### Intent distribution",
        "",
        table(Counter(t["category"] for t in tickets), len(tickets)),
        "",
        "### Severity distribution",
        "",
        table(Counter(t["severity"] for t in tickets), len(tickets)),
        "",
        "### Sentiment distribution",
        "",
        table(Counter(t["sentiment"] for t in tickets), len(tickets)),
        "",
        "## Wave 2: new ticket class (evolving data)",
        "",
        f"* `roaming_issue` tickets: **{len(wave2)}** ({len({t['metadata']['scenario_id'] for t in wave2})} scenarios), "
        f"KB articles: **{len(kb2)}**; dated after the wave-1 window. Not ingested at launch.",
        "",
        "## Evaluation sets (never ingested)",
        "",
        "| set | n | purpose |",
        "|---|---:|---|",
        f"| understanding_eval | {len(evals['understanding_eval'])} | intent / product / severity / sentiment metrics |",
        f"| retrieval_eval | {len(evals['retrieval_eval'])} | retrieval metrics; {len(qrels)} graded judgments "
        f"(grade 2: {grades.get('2', 0)}, grade 1: {grades.get('1', 0)}) |",
        f"| generation_eval | {len(evals['generation_eval'])} | end-to-end pipeline, with reference fix steps |",
        f"| test | {len(evals['test'])} | dev split for threshold selection (keeps the reported sets clean) |",
        f"| novel_intent_eval | {len(evals['novel_intent_eval'])} | wave-2 complaints for unknown-intent / evolving-class tests |",
        f"| groundedness_eval | {len(evals['groundedness_eval'])} | (claim, source, label) triples for E3: "
        + ", ".join(f"{k} {v}" for k, v in Counter(g["label"] for g in evals["groundedness_eval"]).items())
        + " |",
        "",
        "Evaluation complaints are built only from each scenario's **held-out** symptom paraphrases and detail",
        "sentence, so no eval query shares its core problem phrasing with a corpus ticket.",
        "",
        "## Leakage checks (`scripts/verify_splits.py`)",
        "",
    ]
    if leakage:
        out += [
            "| set | id overlap | exact text overlap | template-family overlap | near-dups (cos ≥ "
            f"{leakage['near_dup_threshold']}) | mean max-sim to corpus |",
            "|---|---:|---:|---:|---:|---:|",
        ]
        for name, s in leakage["sets"].items():
            out.append(
                f"| {name} | {s['id_overlap']} | {s['exact_text_overlap']} | {s['template_family_overlap']} | "
                f"{s['near_duplicates']} | {s['max_sim_to_corpus']['mean']} |"
            )
        out += ["", f"Failures: {leakage['failures'] or 'none'}"]
    else:
        out.append("Not run yet.")
    path = ROOT / "data" / "DATASET_STATISTICS.md"
    path.write_text("\n".join(out) + "\n", encoding="utf-8")
    print(f"wrote {path}")


if __name__ == "__main__":
    main()
